import cv2,numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1].astype(float)
# robust chromatic flags with location counts at selected 4px blocks
for y in range(40,144,4):
 parts=[]
 for x in range(0,256,4):
  p=im[y:y+4,x:x+4].mean((0,1)); r,g,b=p
  if r>g*1.16 and r>b*1.22 and r>110: parts.append(f'R{x}')
  elif b>r*1.15 and b>g*1.05 and b>115: parts.append(f'B{x}')
  elif min(p)>190: parts.append(f'W{x}')
 if parts: print(f'{y:3}', ' '.join(parts))
